{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} | {{TAGLINE}}</title>
  <meta name="description" content="{{BUSINESS_NAME}} provides premium HVAC services in {{CITY}}, {{STATE}}. Fast repairs, efficient installs, and honest pricing. Call {{PHONE}}.">
  <meta name="theme-color" content="#2bb3ff">
  <meta property="og:type" content="website">
  <meta property="og:title" content="{{BUSINESS_NAME}} — {{TAGLINE}}">
  <meta property="og:description" content="Trusted HVAC pros for heating, cooling, and air quality. Serving {{CITY}}, {{STATE}}.">
  <meta property="og:image" content="/assets/img/hero-abstract.svg">
  <meta property="og:url" content="/index.html">
  <meta name="twitter:card" content="summary_large_image">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <div class="topbar">
    <div class="container wrap" role="navigation" aria-label="Utility">
      <div class="row">
        <span class="badge" title="Hours">Open: {{HOURS}}</span>
        <span class="badge" title="Service area">Serving {{CITY}}, {{STATE}}</span>
      </div>
      <div class="row">
        <a href="tel:{{PHONE}}" class="row" aria-label="Call us">
          <span>Call</span> <strong>{{PHONE}}</strong>
        </a>
        <span aria-hidden="true">•</span>
        <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
      </div>
    </div>
  </div>
  <header class="header" role="banner">
    <div class="container nav">
      <a class="brand" href="/index.html">
        <span class="logo" aria-hidden="true"></span>
        <span>
          {{BUSINESS_NAME}}
          <small>{{TAGLINE}}</small>
        </span>
      </a>
      <nav class="navlinks" id="mainmenu" aria-label="Main">
        <a href="/index.html" aria-current="page">Home</a>
        <a href="/services.html">Services</a>
        <a href="/pricing.html">Pricing</a>
        <a href="/financing.html">Financing</a>
        <a href="/about.html">About</a>
        <a href="/reviews.html">Reviews</a>
        <a href="/book.html">Book</a>
        <a href="/contact.html">Contact</a>
      </nav>
      <div class="nav-cta">
        <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <button class="menu-btn" aria-controls="mainmenu" aria-expanded="false" aria-label="Toggle menu">Menu</button>
      </div>
    </div>
  </header>

  <main id="content">
    <section class="section hero">
      <div class="container hero-wrap">
        <div>
          <span class="badge">Licensed • Bonded • Insured</span>
          <h1>Comfort engineered. Performance guaranteed.</h1>
          <p class="lead">From high-efficiency installs to 24/7 emergency repairs, {{BUSINESS_NAME}} keeps {{CITY}} homes perfectly heated, cooled, and clean. Transparent pricing. Zero stress.</p>
          <div class="row mt-3">
            <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn secondary" href="/pricing.html">See Pricing</a>
          </div>
          <div class="row mt-4" role="list">
            <div class="stat" role="listitem"><strong>4.9★</strong><span class="help">Average rating</span></div>
            <div class="stat" role="listitem"><strong>15 yrs</strong><span class="help">Serving {{CITY}}</span></div>
            <div class="stat" role="listitem"><strong>98%</strong><span class="help">On-time arrivals</span></div>
          </div>
        </div>
        <div class="hero-media" aria-hidden="true">
          <img src="assets/img/hero-abstract.svg" alt="" style="border-radius:16px; border:1px solid #1d2734; display:block;">
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container grid" style="grid-template-columns: 1.2fr 1fr; align-items:start">
        <div class="card soft">
          <h2>Full-spectrum HVAC services</h2>
          <p class="lead">Expert diagnostics, clean installs, and meticulous maintenance. We treat every system like it's our own.</p>
          <div class="grid mt-3" style="grid-template-columns: repeat(2, 1fr);">
            <div class="feature"><span class="icon">🔥</span><div><strong>Heating</strong><div class="help">Furnaces, boilers, heat pumps</div></div></div>
            <div class="feature"><span class="icon">❄️</span><div><strong>Cooling</strong><div class="help">Central AC, mini-splits</div></div></div>
            <div class="feature"><span class="icon">🌬️</span><div><strong>Air Quality</strong><div class="help">Filtration, UV, humidifiers</div></div></div>
            <div class="feature"><span class="icon">🛠️</span><div><strong>Maintenance</strong><div class="help">Tune-ups & memberships</div></div></div>
          </div>
          <div class="mt-4"><a class="btn" href="/services.html">Explore Services</a></div>
        </div>
        <div class="card">
          <h3>Why homeowners choose us</h3>
          <ul class="list-check mt-2">
            <li>Precise load calculations and duct design</li>
            <li>Top-tier parts with strong warranties</li>
            <li>Neat, respectful crews; no mess left behind</li>
            <li>Upfront line-item quotes—no surprises</li>
          </ul>
          <div class="notice mt-3">Tip: Press <span class="kbd">B</span> to jump to booking on supported UIs.</div>
        </div>
      </div>
    </section>

    <section class="section slim">
      <div class="container kpis" aria-label="Key performance indicators">
        <div class="kpi"><div class="help">Installs this year</div><strong>312</strong></div>
        <div class="kpi"><div class="help">Emergency calls resolved</div><strong>1,128</strong></div>
        <div class="kpi"><div class="help">Energy saved (kWh)</div><strong>480k</strong></div>
        <div class="kpi"><div class="help">Membership renewals</div><strong>96%</strong></div>
      </div>
    </section>

    <section class="section">
      <div class="container">
        <div class="row">
